import json

from taf.rfrl.procedures.resources.python.logger import log_step, log_result, log_input_and_output

from taf.rfrl.procedures.resources.python.SCF import load_value_from_scf, \
    get_param_value_from_loaded_scf


@log_input_and_output
def delta_contains_mismatches(expected_scf, delta_file):
    """
    Checks if delta file contains mismatches between expected and current scf downloaded from BTS.
    If any MOC will be found in 'added' or 'removed' JSON delta file key then 'changed' key is not even
    checked as scf differs with planned delta.

    :param expected_scf: full path with extension to expected scf
    :type expected_scf: str
    :param delta_file: full path with extension to JSON delta file that contains delta file with expected
                       and current scf.
    :type delta_file: str
    :return: True if there are some differences, False otherwise
    :rtype bool
    """
    recommissioning_needed = False

    diff = _find_differences_in_json(delta_file)
    loaded_scf = load_value_from_scf(path=expected_scf)

    if 'added' in diff or 'removed' in diff:
        log_result("There are some added or removed MOCs detected in delta. It means that Your base scf uploaded to "
                   "BTS contains/misses MOCs according to Your target scf created by provided delta injection. "
                   "Please consider updating Your base SCF to avoid unnecessary recommissioning.")
        recommissioning_needed = True

    else:
        log_result("No added or removed MOCs in delta - revalidation in changes begins.")
        if 'changed' not in diff:
            log_result("No changes detected!")
            recommissioning_needed = False
        else:
            if _are_parameters_mismatching(loaded_scf, diff) or _are_list_parameters_mismatching(loaded_scf, diff):
                recommissioning_needed = True
    return recommissioning_needed


@log_input_and_output
def is_json_delta_empty(delta_file):
    """
    Checks if provided json delta is empty, that means there are no added, removed or changed MOCs
    in provided json delta file
    :param delta_file: full path with extension to json delta file
    :type delta_file: str
    :return: True if json delta file is empty, False otherwise
    :rtype: bool
    """
    found_diff = _find_differences_in_json(delta_file)
    if found_diff:
        log_result("Found non-empty objects: {0}".format(found_diff))
    return found_diff == {}


def _find_differences_in_json(delta_file):
    """
    Finds differences in MOC objects in delta json file provided by user.

    :param delta_file: full path to JSON delta file that user wants to check
    :type delta_file: str
    :return: dict that contains non-empty lists in delta json file
    :rtype: dict
    """
    loaded_json = _load_json_delta(delta_file)
    return _find_non_empty_differences(loaded_json)


def _load_json_delta(delta_file):
    """
    Loads json delta file to dictionary variable.

    :param delta_file: full path with extension to JSON delta file user wants to load.
    :type delta_file: str
    :return: json delta file saved to dict
    :rtype: dict
    """
    log_step("Loading delta file from dir: {0}".format(delta_file))
    with open(delta_file, 'rb') as f:
        loaded_json = json.load(f)
    return loaded_json


def _find_non_empty_differences(loaded_json):
    """
    Finds non empty differences in json delta file loaded to dict.
    In delta file there are 3 main keys: added, removed, changed.
    Method reduces keys with empty content to provide only those MOCs
    that differ.

    :param loaded_json: JSON delta file loaded to dictionary variable via _load_json_delta
    :type loaded_json: dict
    :return: JSON delta file loaded to dictionary without empty keys.
    :rtype: dict
    """
    return {k: v for k, v in loaded_json.items() if len(loaded_json[k]) > 0}


def _are_parameters_mismatching(loaded_scf, diff):
    """
    Checks if there are any mismatching parameters between custom_scf and diff's 'changed' key from JSON delta file.

    :param loaded_scf: scf file loaded via load_value_from_scf method from SCF.py
    :type loaded_scf: list(*MySCFParameter)
    :param diff: json delta file loaded to dictionary
    :type diff: dict
    :return: True if there are any mismatching parameters between scf and diff, False otherwise
    :rtype: bool
    """
    log_step("Looking for mismatching parameters between scf and provided delta file")
    return _find_mismatching_parameters(loaded_scf, diff) != []


def _are_list_parameters_mismatching(loaded_scf, diff):
    """
    Checks if there are any mismatching lists' parameters between custom_scf and diff's 'changed' key from
    JSON delta file.

    :param loaded_scf: scf file loaded via load_value_from_scf method from SCF.py
    :type loaded_scf: list(*MySCFParameter)
    :param diff: json delta file loaded to dictionary
    :type diff: dict
    :return: True if there are any mismatching lists' parameters between scf and diff, False otherwise
    :rtype: bool
    """
    log_step("Looking for mismatching parameters in lists between scf and provided delta file")
    return _find_mismatching_list_parameters(loaded_scf, diff) != []


def _find_mismatching_parameters(loaded_scf, diff):
    """
    Finds mismatching parameters between loaded custom scf and json delta file loaded to diff's dict
    (only for 'changed' key!).
    All found mismatches are being written to prepared list and returned as the outcome of method's call.

    :param loaded_scf: scf file loaded via load_value_from_scf method from SCF.py
    :type loaded_scf: list(*MySCFParameter)
    :param diff: json delta file loaded to dictionary
    :type diff: dict
    :return: list of dicts with mismatching parameters - those names, expected and actual values
    :rtype: list(*dict)
    """
    list_of_diffs = []
    log_step("Begins to find mismatching parameters between provided custom_scf and diff dict")
    for moc in diff['changed']:
        for param in moc['params']:
            scf_param_value = get_param_value_from_loaded_scf(loaded_scf=loaded_scf, dist_name=moc['dist_name'],
                                                              abbr=param['name'])
            if param['value'] != scf_param_value:
                log_result("Mismatching value found for parameter '{0}'.\n"
                           "Expected value that is present in custom scf created after delta injection to base SCF "
                           "'{1}'\n Actual value in current SCF on BTS: '{2}'".
                           format(param['name'], scf_param_value, param['value']))
                list_of_diffs.append({'name': param['name'],
                                      'expected_value': scf_param_value,
                                      'current_value': param['value']})
    return list_of_diffs


def _find_mismatching_list_parameters(loaded_scf, diff):
    """
    Finds mismatching lists' parameters between custom scf and json delta file loaded to diff's
    dict (only for 'changed' key!). ll found mismatches are being written to prepared list and returned as
    the outcome of method's call.

    :param loaded_scf: scf file loaded via load_value_from_scf method from SCF.py
    :type loaded_scf: list(*MySCFParameter)
    :param diff: json delta file loaded to dictionary
    :type diff: dict
    :return: list of dicts with mismatching lists' parameters - those names, expected and actual values
    :rtype: list(*dict)
    """
    list_of_diffs = []
    log_step("Begins to find mismatching parameters in lists between provided custom_scf and diff dict")
    for moc in diff['changed']:
        for scf_list in moc['lists']:
            for item in scf_list['items']:
                if item:
                    for param in item['params']:
                        scf_param_value = get_param_value_from_loaded_scf(loaded_scf=loaded_scf,
                                                                          dist_name=moc['dist_name'],
                                                                          abbr=param['name'])
                        if param['value'] != scf_param_value:
                            log_result("Mismatching value found for list parameter '{0}'.\n"
                                       "Expected list parameter value that is present in custom scf created after "
                                       "delta injection to base SCF '{1}'\n"
                                       "Actual list parameter value in current SCF on BTS:: '{2}'".
                                       format(param['name'], scf_param_value, param['value']))
                            list_of_diffs.append({'name': param['name'],
                                                  'expected_value': scf_param_value,
                                                  'current_value': param['value']})
    return list_of_diffs
